<?php
if(!defined('ABSPATH')){exit;}
final class NVConsult_Core_AI_Assistant{
 public static function init():void{add_action('rest_api_init',[self::class,'routes']);}
 public static function routes():void{register_rest_route('nvconsult/v1','/ai/case-summary',['methods'=>WP_REST_Server::CREATABLE,'callback'=>[self::class,'summary'],'permission_callback'=>static fn()=>current_user_can('nvconsult_manage_applications'),'args'=>['application_id'=>['required'=>true,'sanitize_callback'=>'absint']]]);}
 public static function summary(WP_REST_Request$r){$id=absint($r['application_id']);if(get_post_type($id)!=='nv_application')return new WP_Error('invalid_application',__('Invalid application.','nvconsult-core'),['status'=>404]);$key=getenv('OPENAI_API_KEY');if(!$key)return new WP_Error('ai_not_configured',__('AI is not configured. Set OPENAI_API_KEY on the server.','nvconsult-core'),['status'=>503]);$status=(string)get_post_meta($id,'_nvconsult_status',true);$activity=array_slice(NVConsult_Core_Activity::items($id,true),0,20);$safe=[];foreach($activity as$i)$safe[]=['type'=>$i['type'],'text'=>wp_strip_all_tags($i['text']),'time'=>$i['time']];$prompt="Summarize this immigration/recruitment/education consultancy case for an authorized staff member. Do not invent facts. Identify current status, pending actions, risks, and recommended next step.\nStatus: ".$status."\nRecent activity: ".wp_json_encode($safe);$body=['model'=>apply_filters('nvconsult_openai_model','gpt-5-mini'),'input'=>$prompt,'max_output_tokens'=>500];$res=wp_remote_post('https://api.openai.com/v1/responses',['timeout'=>45,'headers'=>['Authorization'=>'Bearer '.$key,'Content-Type'=>'application/json'],'body'=>wp_json_encode($body)]);if(is_wp_error($res))return$res;$code=wp_remote_retrieve_response_code($res);$data=json_decode(wp_remote_retrieve_body($res),true);if($code<200||$code>=300)return new WP_Error('openai_error',__('AI request failed.','nvconsult-core'),['status'=>502,'upstream_status'=>$code]);$text='';foreach(($data['output']??[])as$o)foreach(($o['content']??[])as$c)if(($c['type']??'')==='output_text')$text.=(string)($c['text']??'');if(!$text)return new WP_Error('empty_ai_response',__('AI returned no summary.','nvconsult-core'),['status'=>502]);add_post_meta($id,'_nvconsult_history',['type'=>'ai','message'=>__('AI case summary generated by staff.','nvconsult-core'),'time'=>current_time('mysql'),'user_id'=>get_current_user_id()]);return rest_ensure_response(['summary'=>$text]);}
}
